-- Seed data for local development and demos.
-- GENERATED by tool/generate_seed.dart (groups come from the
-- in-app club catalog). Edit the script, not this file.

-- Catalog clubs, societies, design teams and first-year groups.
on conflict (slug) do nothing;

-- Faculties and student associations (not in the club catalog: these open
-- the placeholder Faculty / Club page in the app).
    'The undergraduate student union for McGill''s downtown campus.'),
  ('ssmu-frosh-committee', 'SSMU Frosh Committee', 'student_association', 'Student association',
    'Runs Frosh Week for incoming students.'),
  ('pgss', 'Post-Graduate Students'' Society (PGSS)', 'student_association', 'Student association',
    'Represents McGill''s graduate students and postdocs.'),
  ('faculty-of-engineering', 'Faculty of Engineering', 'faculty', 'Faculty', null),
  ('faculty-of-science', 'Faculty of Science', 'faculty', 'Faculty', null),
  ('faculty-of-arts', 'Faculty of Arts', 'faculty', 'Faculty', null),
  ('desautels-faculty-of-management', 'Desautels Faculty of Management', 'faculty', 'Faculty', null),
  ('schulich-school-of-music', 'Schulich School of Music', 'faculty', 'Faculty', null),
  ('aus', 'Arts Undergraduate Society (AUS)', 'faculty_affiliation', 'Faculty association', null),
  ('sus', 'Science Undergraduate Society (SUS)', 'faculty_affiliation', 'Faculty association', null),
  ('eus', 'Engineering Undergraduate Society (EUS)', 'faculty_affiliation', 'Faculty association', null),
  ('mus', 'Management Undergraduate Society (MUS)', 'faculty_affiliation', 'Faculty association', null)
on conflict (slug) do nothing;

-- Sample events, dated relative to when the seed runs.
-- Coordinates are approximate building locations on the downtown campus.
  group_id, title, ai_synopsis, full_description, starts_at, ends_at,
  location_name, latitude, longitude, tags, is_froshie_event
)
select g.id, e.title, e.ai_synopsis, e.full_description,
  date_trunc('hour', now()) + e.starts_in, date_trunc('hour', now()) + e.starts_in + e.duration,
  e.location_name, e.latitude, e.longitude, e.tags, e.is_froshie_event
from (values
  ('ssmu-frosh-committee', 'Frosh Week Kickoff',
    'Kick off Frosh Week on Lower Field: meet your Frosh group, grab your kit, and enjoy music, food trucks and games. Bring your student ID.',
    'Welcome to McGill! Frosh Week starts here. Meet your Frosh group and leaders, pick up your Frosh kit and t-shirt, and get the full schedule for the week. There will be music, food trucks, games on the field and a short welcome from SSMU. The event is alcohol-free and open to all first-year students, including U0s and U1s coming from CEGEP. Bring your student ID to check in. In case of rain, the kickoff moves to the SSMU Ballroom.',
    interval '2 days 19 hours', interval '3 hours',
    'Lower Field', 45.5040, -73.5760, array['frosh', 'social', 'outdoors'], true),
  ('ssmu-frosh-committee', 'Froshie Campus Scavenger Hunt',
    'Team up with other first-years to find landmarks across campus. Prizes for the top three teams.',
    'Learn your way around campus before classes start. Teams of four race to find clues at the Roddick Gates, Redpath Museum, McLennan Library, the Three Bares fountain and more. Each stop has a short challenge. Finish at the Y-intersection for snacks and the prize ceremony. Teams are formed on the spot, so come alone or with friends.',
    interval '3 days 13 hours', interval '2 hours',
    'Roddick Gates', 45.5048, -73.5772, array['frosh', 'social'], true),
  ('aus', 'Arts Welcome Mixer',
    'Meet other Arts students and AUS departmental associations over snacks and live music in Leacock.',
    'Every Arts department association will be there with a table, so it''s the easiest way to find your people. Grab free snacks, enter a raffle for AUS merch, and hear a short set from a student jazz trio. Open to all Arts and Arts & Science students.',
    interval '4 days 17 hours', interval '2 hours',
    'Leacock Building, Lobby', 45.5043, -73.5745, array['social', 'faculty'], false),
  ('eus', 'Engineering Design Team Fair',
    'Meet McGill''s engineering design teams, from rocketry to robotics, and learn how to join this term.',
    'Over a dozen design teams will show off their builds and explain how recruitment works. Bring a résumé if you have one, but it''s not required. First-years are especially welcome: most teams have junior roles with no experience needed.',
    interval '5 days 11 hours', interval '4 hours',
    'McConnell Engineering Building', 45.5059, -73.5763, array['engineering', 'careers'], false),
  ('sus', 'Science Study Night',
    'Quiet, catered group study session with upper-year tutors on hand for first-year science courses.',
    'Bring your problem sets for CHEM 110, PHYS 101, BIOL 111 and MATH 140/141. Upper-year tutors from SUS rotate between tables to help. Coffee and snacks provided. Silent and collaborative rooms available.',
    interval '6 days 18 hours', interval '3 hours',
    'Redpath Library, Cyberthèque', 45.5040, -73.5755, array['academic', 'study'], false),
  ('schulich-school-of-music', 'Lunchtime Jazz in Pollack Hall',
    'Free 45-minute jazz set by Schulich students. Walk in any time.',
    'Take a break from classes with a free performance by student combos from the Schulich School of Music jazz program. No tickets needed. Seating is first come, first served.',
    interval '7 days 12 hours', interval '45 minutes',
    'Pollack Hall', 45.5064, -73.5742, array['music', 'arts'], false)
) as e(slug, title, ai_synopsis, full_description, starts_in, duration,
       location_name, latitude, longitude, tags, is_froshie_event)
join public.groups g on g.slug = e.slug;

-- One upcoming event per catalog club category, so club pages aren't empty.
select g.id,
  g.name || ' Info Session',
  'Find out what ' || g.name || ' does this term and how to get involved. Newcomers welcome.',
  'Come meet the executive team of ' || g.name || '. We''ll go over this term''s events, how to become a member, and answer any questions. No experience needed.',
  date_trunc('hour', now()) + interval '1 day' * (2 + row_number() over (order by g.slug) % 10) + interval '17 hours',
  'University Centre (SSMU Building)',
  array['info-session']
from public.groups g
where g.type = 'club'
  and g.slug in (
    select distinct on (category) slug from public.groups
    where type = 'club' order by category, slug
  );
